import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.ChTAMbUy.js";const u=JSON.parse('{"title":"API Keys","description":"","frontmatter":{},"headers":[],"relativePath":"development/platform/api_keys.md","filePath":"versions/development/platform/api_keys.md","lastUpdated":1791568428000}'),o={name:"development/platform/api_keys.md"};function r(n,e,l,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="api-keys" tabindex="-1">API Keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API Keys&quot;">​</a></h1><p>API keys provide scoped programmatic access to selected prokube services without a browser session. Use them wherever a script, CI job, or external client calls a prokube service.</p><p>Each key can be scoped to specific services/workloads instead of the whole workspace, sent with either of two client authentication headers, and given an optional expiration date.</p><p>A key belongs to the workspace that was selected when it was created. prokube routes public API traffic through <a href="./agent_gateway.html">Agent Gateway</a>, the shared routing and policy layer for API clients, but you do not need to configure Agent Gateway to create a key.</p><p>Use API keys when a workload or external client needs repeatable access without an interactive login. For browser-based work in the prokube UI, use your normal user session instead.</p><h2 id="manage-keys-in-the-ui" tabindex="-1">Manage Keys in the UI <a class="header-anchor" href="#manage-keys-in-the-ui" aria-label="Permalink to &quot;Manage Keys in the UI&quot;">​</a></h2><p>Open <strong>API Keys</strong> from the sidebar under <strong>Serving</strong>. Select the workspace before creating or editing keys.</p><p>Regular users see only their own keys in the selected workspace. Administrators can see and manage all keys in the workspace.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/api-key-list.png" alt="API Keys list with filters and key metadata" loading="lazy"></p><p>The table shows each key&#39;s metadata, such as owner, status, expiration, and scopes, but never the full key value. The key prefix helps identify which key a client is using without exposing the secret.</p><h2 id="ownership-and-workspace-scope" tabindex="-1">Ownership and Workspace Scope <a class="header-anchor" href="#ownership-and-workspace-scope" aria-label="Permalink to &quot;Ownership and Workspace Scope&quot;">​</a></h2><p>API keys are scoped by both workspace and owner:</p><ul><li>A key can only grant access inside the workspace where it was created.</li><li>Regular users can list, edit, rotate, disable, and delete only their own keys.</li><li>Administrators can list and manage all keys in the selected workspace.</li></ul><p>For shared automation, avoid personal long-lived keys where possible. Prefer a key created by the user or service account that owns the automation, and document where the secret is stored.</p><h2 id="create-a-key" tabindex="-1">Create a Key <a class="header-anchor" href="#create-a-key" aria-label="Permalink to &quot;Create a Key&quot;">​</a></h2><p>Click <strong>Create Key</strong> and fill in the form:</p><ul><li><strong>Name</strong>: a descriptive name for the key.</li><li><strong>Description</strong>: optional context for who or what uses the key.</li><li><strong>Expiration Date</strong>: optional. Use expirations for automation keys unless there is a clear rotation process.</li><li><strong>Client Authentication</strong>: choose how clients send the key.</li><li><strong>Select Services</strong>: choose the services this key may access.</li></ul><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/create-key-ui.png" alt="Create API Key dialog with client authentication and service selection" loading="lazy"></p><p>The service list is built from services available in the selected workspace. It can include:</p><ul><li><strong>Models</strong> for KServe and LLM endpoints.</li><li><strong>MCP servers</strong> for tool access.</li><li><strong>Memory stores</strong> exposed through MCP-compatible routes.</li><li><strong>A2A agents</strong> for kagent agent-to-agent access.</li><li><strong>Knative services</strong> exposed through gateway routes.</li></ul><p>Besides individual services, you can select aggregate scopes such as <strong>All MCP servers</strong> or <strong>All AI models</strong>. They also cover matching services created later. <strong>Full workspace access</strong> covers every service in the workspace. Keys with <strong>All AI models</strong>, <strong>All external AI models</strong>, or <strong>Full workspace access</strong> must use the Bearer format.</p><p>Admin-granted <a href="./../admin/external_models.html">external models</a> are not listed as individual services. To reach them, use a Bearer-format key with <strong>All external AI models</strong>, <strong>All AI models</strong>, or <strong>Full workspace access</strong>. These scopes cover every granted model in the workspace; a key cannot be limited to one granted model.</p><p>Select only the services the client needs. If no services are available, deploy or expose the service first, then create the key.</p><p>Service-specific scopes are the default choice for production clients. They reduce blast radius if a key is exposed and make it clear which integration depends on which platform service.</p><h2 id="client-authentication" tabindex="-1">Client Authentication <a class="header-anchor" href="#client-authentication" aria-label="Permalink to &quot;Client Authentication&quot;">​</a></h2><p>Choose the authentication format expected by the client:</p><table tabindex="0"><thead><tr><th>Format</th><th>Use when</th></tr></thead><tbody><tr><td><code>Authorization: Bearer &lt;key&gt;</code></td><td>The client is OpenAI-compatible or expects bearer authentication. This is the recommended format for LLM clients.</td></tr><tr><td><code>x-api-key: &lt;key&gt;</code></td><td>The client cannot set an <code>Authorization</code> header, or an existing integration already sends <code>x-api-key</code>. Not available for keys with <strong>All AI models</strong>, <strong>All external AI models</strong>, or <strong>Full workspace access</strong>.</td></tr></tbody></table><p>Use the service page for the exact URL and request body. Examples:</p><p>OpenAI-compatible model clients commonly use bearer authentication. For a model deployed through <a href="./../agentops/llm_serving.html">LLM Serving</a>, <code>&lt;route-id&gt;</code> is the deployment name; for an admin-granted <a href="./../admin/external_models.html">external model</a>, it is the route ID chosen in the grant:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://&lt;your-prokube-domain&gt;/svc/ai/&lt;workspace&gt;/models/&lt;route-id&gt;/v1/chat/completions&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;api-key&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;model&quot;:&quot;&lt;model&gt;&quot;,&quot;messages&quot;:[{&quot;role&quot;:&quot;user&quot;,&quot;content&quot;:&quot;Hello&quot;}]}&#39;</span></span></code></pre></div><p>MCP clients take the key in their server configuration. The MCP server&#39;s <strong>Overview</strong> tab in the prokube UI shows a ready-to-copy configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;&lt;server&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://&lt;your-prokube-domain&gt;/svc/mcp/&lt;workspace&gt;/&lt;server&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer &lt;api-key&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="copy-the-key-value" tabindex="-1">Copy the Key Value <a class="header-anchor" href="#copy-the-key-value" aria-label="Permalink to &quot;Copy the Key Value&quot;">​</a></h2><p>prokube shows the full key value only after creation or rotation. Copy it immediately and store it in your secret manager.</p><p>If you close the dialog without copying the key, create a new key or rotate the existing key. The old full value cannot be recovered from the UI.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/api-key-shown-once.png" alt="One-time API key display with copy action and client example" loading="lazy"></p><h2 id="manage-existing-keys" tabindex="-1">Manage Existing Keys <a class="header-anchor" href="#manage-existing-keys" aria-label="Permalink to &quot;Manage Existing Keys&quot;">​</a></h2><p>From the API Keys page you can:</p><ul><li>search keys by name or prefix;</li><li>filter by status, expiration, and scope type;</li><li>edit metadata, expiration, enabled state, and service scopes;</li><li>disable, rotate, or delete keys.</li></ul><p>Disable a key when you need temporary revocation or want to test whether a client still depends on it. Delete a key when it is no longer needed.</p><p>Rotating a key invalidates the old value immediately. Update every client or secret that uses the key before relying on the rotated value.</p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/api-key-edit-disable-rotate-menu.png" alt="API key action menu with edit, disable, rotate, and delete actions" style="max-width:360px;width:100%;height:auto;"><h2 id="usage-dashboard" tabindex="-1">Usage Dashboard <a class="header-anchor" href="#usage-dashboard" aria-label="Permalink to &quot;Usage Dashboard&quot;">​</a></h2><p>Switch to the <strong>Usage</strong> tab on the API Keys page to see how keys in the selected workspace are being used. The dashboard covers requests that Agent Gateway authenticated with a key. It does not cover internal in-mesh traffic (see <a href="./agent_gateway.html#public-vs-internal-traffic">Agent Gateway: Public vs. Internal Traffic</a>).</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/api-key-usage-tab.png" alt="API key usage dashboard with request trend, estimated LLM usage, and per-key activity" loading="lazy"></p><h3 id="time-window-and-cohorts" tabindex="-1">Time Window and Cohorts <a class="header-anchor" href="#time-window-and-cohorts" aria-label="Permalink to &quot;Time Window and Cohorts&quot;">​</a></h3><p>Choose a <strong>time window</strong> to control both the summary numbers and the request trend chart below them. Options are Last hour, Last 24 hours (default), Last 7 days, and Last 30 days.</p><p>The dashboard shows up to three cohort cards, split by how a request was attributed:</p><ul><li><strong>External attributed</strong>: requests attributed to an authenticated key. This is the only cohort regular users see.</li><li><strong>Internal aggregate</strong> and <strong>Unattributed public</strong>: aggregate-only counts, visible to administrators. These are never distributed across individual keys, so they cannot be used to identify which key or workload generated a given request.</li></ul><p>The <strong>request trend</strong> chart plots request volume per time bucket for the selected window. If Prometheus retained only part of the window, the dashboard shows a note that the trend is truncated rather than silently showing partial data as complete.</p><h3 id="token-and-cost-estimate" tabindex="-1">Token and Cost Estimate <a class="header-anchor" href="#token-and-cost-estimate" aria-label="Permalink to &quot;Token and Cost Estimate&quot;">​</a></h3><p>The <strong>Estimated LLM usage</strong> panel shows input tokens, output tokens, and an estimated cost for LLM traffic in the window. Estimated cost is derived from a model pricing catalog:</p><ul><li>If pricing is missing for some models in the window, the panel notes that the estimate excludes those models.</li><li>If no pricing data is available at all, the panel says catalog pricing is unavailable rather than showing a misleading total.</li></ul><p>Token and cost figures apply only to LLM (<code>/svc/ai</code>) traffic. Other path families report request counts but not tokens or cost.</p><h3 id="usage-by-key" tabindex="-1">Usage by Key <a class="header-anchor" href="#usage-by-key" aria-label="Permalink to &quot;Usage by Key&quot;">​</a></h3><p>The <strong>Usage by key</strong> table lists per-key activity for the window:</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td>Key</td><td>Key name. A deleted key that still has recorded usage shows as <strong>Historical</strong> rather than disappearing from the table.</td></tr><tr><td>Owner</td><td>The user who created the key.</td></tr><tr><td>Requests</td><td>Total requests attributed to the key in the window.</td></tr><tr><td>Failed</td><td>Requests that failed (non-2xx/3xx) in the window.</td></tr><tr><td>LLM tokens</td><td>Input + output tokens, for <code>/svc/ai</code> traffic only.</td></tr><tr><td>Estimated cost</td><td>Estimated cost for the key&#39;s LLM traffic in the window.</td></tr><tr><td>Last Active</td><td>Approximate time since the key&#39;s last recorded request, bounded by the selected window and its sampling granularity, not an exact last-used timestamp.</td></tr></tbody></table><p>Regular users see <strong>Keys owned by you</strong>. Administrators see <strong>All workspace keys</strong>. Keys with no recorded activity in the window are omitted, except historical (deleted) keys that administrators can still see for auditing.</p><h3 id="reading-the-numbers-correctly" tabindex="-1">Reading the Numbers Correctly <a class="header-anchor" href="#reading-the-numbers-correctly" aria-label="Permalink to &quot;Reading the Numbers Correctly&quot;">​</a></h3><ul><li>Request counts, tokens, and cost are estimates for observability, not billing records.</li><li>Prometheus retention limits how far back the dashboard can report. Older activity outside the retention window will not appear even if the key was used.</li><li>If usage telemetry is not configured for the cluster, the dashboard shows a notice instead of numbers. Contact your administrator if you expect usage data and see this notice.</li></ul><h2 id="security-guidance" tabindex="-1">Security Guidance <a class="header-anchor" href="#security-guidance" aria-label="Permalink to &quot;Security Guidance&quot;">​</a></h2><ul><li>Prefer service-specific keys over broad workspace access.</li><li>Set an expiration date for automation keys where possible.</li><li>Store keys in a secret manager, not in source code, notebooks, screenshots, shell history, or issues.</li><li>Rotate keys when ownership changes, a client is redeployed, or a key may have been exposed.</li><li>Disable a key first if you need to test impact before deleting it.</li><li>Delete keys that are no longer used.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>No services are available when creating a key</td><td>Confirm the target service exists in the selected workspace and is exposed through Agent Gateway-supported routes.</td></tr><tr><td>A key is not visible to another user in the same workspace</td><td>Regular users only see keys they created. Ask an administrator if shared visibility or management is required.</td></tr><tr><td>Client receives <code>401</code> or <code>403</code></td><td>Confirm the key is enabled, not expired, sent with the selected authentication header, and scoped to the target service.</td></tr><tr><td>Client can call one service but not another</td><td>The key is scoped to selected services. Edit the key or create a new key for the additional service.</td></tr><tr><td>Client stopped working after rotation</td><td>The old key value stopped working immediately. Update the client secret or environment variable with the new value.</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./agent_gateway.html">Agent Gateway</a></li><li><a href="./../agentops/mcp_servers.html">MCP Servers</a></li><li><a href="./../mlops/model_serving.html">Model Serving</a></li><li><a href="./../mlops/knative.html">Serverless</a></li></ul>`,66)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
